#include <iostream>
#include <vector>
#include <string>
using namespace std;

void climb(int remaining, vector<int>& current, vector<string>& out) {
    if (remaining == 0) {
        string line;
        for (size_t i = 0; i < current.size(); i++) line += (i ? "+" : "") + to_string(current[i]);
        out.push_back(line);
        return;
    }
    for (int step = 1; step <= 3; step++) {
        if (step <= remaining) {
            current.push_back(step);
            climb(remaining - step, current, out);
            current.pop_back();
        }
    }
}

int main() {
    long long n;
    cin >> n;

    vector<string> out;
    vector<int> current;
    climb((int)n, current, out);
    for (const string& line : out) cout << line << "\n";

    return 0;
}

